WITH with_windows AS (SELECT id, customer_id, plan, monthly_fee, status, RANK() OVER (PARTITION BY customer_id ORDER BY monthly_fee DESC NULLS FIRST) AS monthly_fee_rank, NTILE(3) OVER (ORDER BY monthly_fee, id) AS monthly_fee_bucket, FIRST_VALUE(monthly_fee, TRUE) OVER (PARTITION BY plan ORDER BY monthly_fee, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_monthly_fee FROM subscriptions WHERE monthly_fee BETWEEN 90 AND 190) SELECT s.id, s.customer_id, s.plan, s.monthly_fee, s.status, s.monthly_fee_rank, s.monthly_fee_bucket, (SELECT AVG(t2.balance) FROM accounts t2 WHERE t2.customer_id = s.customer_id) AS avg_account_balance FROM with_windows s ORDER BY customer_id NULLS LAST, monthly_fee_bucket DESC
